         throw malformed("deep schema");
      if (cached != null)
         return cached;
      if (!active.add(name))
         throw malformed("recursive schema");
      int height = 0;
      for (Field f : s.messages.get(name).fields)
         if (s.messages.containsKey(f.typeName))
            height = Math.max(height, 1 + visit(s, f.typeName, active, heights, depth + 1));
